@pytest.mark.parametrize("mode,corrupt", [("control", False), ("reserve", False), ("control", True), ("reserve", True)]) def test_full_four_generation_policy_and_checkpoint_tie_state(mode, corrupt): # Repeated synthetic fitness batches exercise accumulated tie state and changing # breeder identifiers; no genotype arrays or scientific evaluations exist. seed = 701 rng = torch.Generator().manual_seed(seed + S.TIE_SEED) parents = list(range(32)) lines = [ { "event": "founders", "sampled": 0, "ids": [0], "copies": [{"id": i, "parent": 0, "ops": {"mut": []}} for i in range(1, 32)], } ] curves = [] spec = types.SimpleNamespace(hash64=lambda seed, purpose, index, life: purpose * 100000 + index * 100 + life) for generation in range(4): row, curve, _, _, _ = fixture(mode, generation, ties=True, parents=parents, generator=rng) row["seeds"] = [S.life_seed(spec, seed, 1, generation, j) for j in range(3)] row["recheck"]["seeds"] = [S.life_seed(spec, seed, 1, generation, j) for j in range(3, 7)] row["T"] = curve["T"] = 1024 lines.append(row) curves.append(curve) parents = row["survivors"] state = { "ids": torch.tensor(parents), "fitness": torch.tensor(lines[-1]["fitness"], dtype=torch.float64), "tie_generator": rng.get_state(), } if corrupt: state["tie_generator"] = torch.Generator().manual_seed(1).get_state() with pytest.raises(ValueError): S.audit_lineage(lines, curves, state, seed, spec, mode, P.POLICY) else: > receipt = S.audit_lineage(lines, curves, state, seed, spec, mode, P.POLICY) ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^
